parameters.jsCode:
// Antwort für den Agent. Er liest 'bestaetigung' im Gespräch vor, deshalb
// muss der Satz sprechbar sein — keine IDs, keine Zeitstempel, kein 'ISO'.

const vormerkung = $('Slot vormerken').first().json.body ?? {};

if (!vormerkung.ok) {
  return [{ json: {
    ok: false,
    grund: vormerkung.grund ?? 'fehler',
    bestaetigung: vormerkung.bestaetigung
      ?? 'Das hat leider nicht geklappt. Ich notiere den Wunsch, und Damjan meldet sich.',
  } }];
}

// Ausdrücklich den Google-Node ansprechen, nicht $input. Vor diesem Node
// liegt 'Kalender-ID sichern' — $input.first() wäre also dessen Antwort,
// und die ist immer in Ordnung. Der Fehler fiele erst auf, wenn jemand
// einen Termin sucht, der nie im Kalender ankam.
const google = $('Google: Termin anlegen').first().json;
// Bei onError liefert der Node ein { error: … } statt einer Antwort.
const imKalender = !google?.error &&
  (google?.statusCode === undefined || (google.statusCode >= 200 && google.statusCode < 300));
if (google?.error) console.error(`Kalendereintrag fehlgeschlagen: ${google.error.message ?? google.error}`);

const start = new Intl.DateTimeFormat('de-DE', {
  timeZone: 'Europe/Berlin', weekday: 'long', day: 'numeric', month: 'long',
  hour: '2-digit', minute: '2-digit',
}).format(new Date(vormerkung.start));

return [{ json: {
  ok: true,
  buchung_id: vormerkung.buchung_id,
  im_kalender: imKalender,
  // In beiden Fällen dieselbe Zusage. Der Termin steht — ob der
  // Kalendereintrag es schon geschafft hat, ist nicht das Problem des
  // Anrufers. Fehlt er, sieht Damjan die Buchung trotzdem.
  bestaetigung: `Der Termin steht: ${start}. Damjan ruft Sie dann an.`,
} }];
